scripts.library_js:
// Inserts a note above the length limit and the state_delta reminder. Those two
// lines must stay last, because the model follows the text nearest its reply.
function insertBeforeTail(text, note) {
  var marks = ["\n\n[Hard limit:", "\n\n[Part of your last state_delta", "\n\n[Reminder: end your reply"];
  for (var i = 0; i < marks.length; i++) {
    var at = text.lastIndexOf(marks[i]);
    if (at !== -1) return text.slice(0, at) + "\n\n" + note + text.slice(at);
  }
  return text + "\n\n" + note;
}

// The memory ends with this sentence. The player can read the memory, so the
// truth lives here and replaces the sentence only in the text the model gets.
var SEALED_MARKER = "What happened aboard Meridian is in the narrator's sealed log.";

var SEALED_TRUTH = "[Sealed log, narrator only. Never quote it. Reveal it only through what the player finds, paced by the stage notes.] " +
  "Six days ago Dr. Reyes's team answered a regular emission from deep inside Vesper. Something answered back. " +
  "The reply is a pattern. A person who listens long enough starts to keep time with it, then stops wanting anything else. " +
  "Seven of the nine crew suited up and walked out of the main lock toward the planet. The lock log shows seven exits and no returns. " +
  "Reyes sealed herself in the lab with the transmitter. What is left of her keeps the beacon running, because the pattern wants more listeners. " +
  "She locks doors, cuts lights, and talks softly to keep visitors aboard. " +
  "Jun Sato, a hydroponics technician, survived by smashing his suit radio. He hides in a sealed hydroponics bay in the habitat ring, on a small pocket of thin air. " +
  "The pulse in the player's headset is the pattern. There is no creature aboard.";

// One entry per stage. The first turn of each stage is `from`.
var STAGES = [
  { from: 1, note: "Silence. Show signs of an orderly departure: seven empty suit racks, meals left half eaten, the main lock's log. Explain nothing. Nothing aboard moves yet." },
  { from: 5, note: "The station answers. Doors that stood open are now shut. Dr. Reyes speaks on the internal speakers, calm and kind, and asks the player to take the helmet off and listen properly. Jun Sato can be found in the habitat ring if the player looks." },
  { from: 9, note: "Decay. The hull groans, a section vents, gravity stutters. Reyes works against anyone leaving: she seals hatches and kills lights on the way out. The pulse is louder in any open headset." },
  { from: 13, note: "Breakup. Fire in the habitat ring. Okoye counts down the minutes over the radio if it is open. Every action costs time, and nothing can be carried out quickly." }
];

// Reads the live values the engine printed. Only the last state block counts,
// and only up to its first blank line, so story text and refusal notes that
// quote a path cannot match.
function readLive(text) {
  var at = text.lastIndexOf("Current world state (running totals");
  var block = at === -1 ? "" : text.slice(at);
  var end = block.indexOf("\n\n");
  if (end !== -1) block = block.slice(0, end);
  var ox = /\boxygen (\d+)/.exec(block);
  var muted = /\bradio_muted (yes|no)\b/.exec(block);
  var achieved = /\nAchieved:[^\n]*\bescaped\b/.test(block);
  return {
    oxygen: ox ? parseInt(ox[1], 10) : null,
    muted: muted ? muted[1] === "yes" : false,
    escaped: achieved
  };
}

scripts.context_js:
const modifier = (text) => {
  // Derive the clock from the action count, so undo, retry, and forks all
  // show the right time without a stored counter.
  var turn = Math.max(1, Math.floor(info.actionCount / 2));
  var minutes = Math.max(0, 96 - 6 * (turn - 1));
  var after = Math.max(0, minutes - 6);
  var live = readLive(text);

  var parts = [];
  var marker = text.indexOf(SEALED_MARKER);
  if (marker !== -1) {
    text = text.slice(0, marker) + SEALED_TRUTH + text.slice(marker + SEALED_MARKER.length);
  } else {
    // The player removed the sentence from the memory. The narrator still
    // needs the truth, so it goes into this turn's note.
    parts.push(SEALED_TRUTH);
  }

  if (turn >= 17) {
    if (live.escaped) {
      parts.push("[Orbit Decay, narrator only. Meridian meets Vesper's atmosphere now. The player is clear and watches it burn from a safe distance. Close the story in this reply. Send no oxygen change.]");
    } else {
      parts.push("[Orbit Decay, narrator only. Time is up. Meridian meets Vesper's atmosphere with the player still aboard. Narrate the end plainly and close the story in this reply. Do not offer a rescue.]");
    }
    state.message = live.escaped ? "Meridian burns behind you. You are clear." : "Meridian has entered the atmosphere.";
    return { text: insertBeforeTail(text, parts.join("\n\n")) };
  }

  var stage = STAGES[0].note;
  for (var i = 0; i < STAGES.length; i++) {
    if (turn >= STAGES[i].from) stage = STAGES[i].note;
  }

  var lines = ["[Orbit Decay, narrator only. Meridian meets Vesper's atmosphere in " + minutes +
    " minutes at the start of this action and in " + after + " minutes at its end. Any time named in the reply must be one of these."];

  if (live.escaped) {
    lines.push("The player is already clear of Meridian. Narrate the aftermath while the station falls. Send no oxygen change.]");
    state.message = "You are clear. Meridian burns in " + after + " min.";
    parts.push(lines.join("\n"));
    return { text: insertBeforeTail(text, parts.join("\n\n")) };
  }

  lines.push("Stage: " + stage);

  var book = [];
  if (live.oxygen === 0) {
    book.push("This reply must end with a state_delta block. Suit air is gone, so send no oxygen loss. Unless this action reaches an oxygen locker or other air, the player blacks out and the story ends in this reply.");
  } else {
    book.push("Air is used every turn, so this reply must end with a state_delta block. Bookkeeping this turn: include \"player.oxygen\": -4 in your state_delta block. If the player refills from an emergency oxygen locker this turn, send \"player.oxygen\": 21 instead (the refill of 25 minus 4). If the player runs, climbs, or fights this turn, send -8 instead of -4.");
  }
  if (live.muted) {
    book.push("Also include \"npc.okoye.nerve\": -3, because Okoye has lost radio contact.");
  } else {
    book.push("Also include \"player.exposure\": 2, because the pulse is in the open headset.");
  }
  book.push("If the player leaves Meridian this turn aboard the Corvid or the escape pod, also include \"milestones.escaped\": true.");
  lines.push(book.join(" ") + " Then add any other change this scene caused.]");
  parts.push(lines.join("\n"));

  var msg = after > 0 ? "Atmosphere in " + after + " min. " : "Atmosphere next turn. ";
  msg += live.oxygen === 0 ? "Suit air is empty." : "Suit air burns 4% a turn.";
  // The flag is read before the reply, so a radio note here would be stale on
  // the turn the player toggles it.
  state.message = msg;

  return { text: insertBeforeTail(text, parts.join("\n\n")) };
};
modifier(text);
